const fs=require("fs");const path=require("path");const svg2ttf=require("svg2ttf");const ttf2woff=require("ttf2woff");const HERE=__dirname;const SVG=path.join(HERE,"svg");const DIST=path.join(HERE,"dist");const FONT="icc-icons";const PREFIX="icc-icon";const VERSION="1.0.0";const ICONS=[["coin",59648,"Limite / valor"],["calendar",59649,"Prazos"],["calculator",59650,"Taxa de juros"],["user-tie",59651,"Avalista"],["tags",59652,"TAC / taxa"],["pie-chart",59653,"Comprometimento de renda"],["facebook",59654,"Facebook"],["linkedin",59655,"LinkedIn"],["x-twitter",59656,"X (Twitter)"],["whatsapp",59657,"WhatsApp"]];fs.mkdirSync(DIST,{recursive:true});(async()=>{const{SVGIcons2SVGFontStream:SVGIcons2SVGFont}=await import("svgicons2svgfont");const ttf2woff2=(await import("ttf2woff2")).default;const stream=new SVGIcons2SVGFont({fontName:FONT,fontHeight:1e3,descent:150,normalize:false,centerHorizontally:false,log:()=>{}});const chunks=[];stream.on("data",c=>chunks.push(c));stream.on("end",()=>{const svgFont=chunks.map(String).join("");fs.writeFileSync(path.join(DIST,`${FONT}.svg`),svgFont);const ttf=Buffer.from(svg2ttf(svgFont,{version:"1.0",description:"ICC Serra icon font"}).buffer);fs.writeFileSync(path.join(DIST,`${FONT}.ttf`),ttf);fs.writeFileSync(path.join(DIST,`${FONT}.woff`),Buffer.from(ttf2woff(ttf).buffer));fs.writeFileSync(path.join(DIST,`${FONT}.woff2`),ttf2woff2(ttf));for(const f of["svg","ttf","woff","woff2"]){const p=path.join(DIST,`${FONT}.${f}`);console.log(`${f.padEnd(5)} ${(fs.statSync(p).size/1024).toFixed(1)} KB`)}});for(const[name,code]of ICONS){const file=path.join(SVG,`${name}.svg`);if(!fs.existsSync(file))throw new Error(`faltando ${file}`);const g=fs.createReadStream(file);g.metadata={unicode:[String.fromCodePoint(code)],name:name};stream.write(g)}stream.end()})();